@webjs:(function(){
  var CH='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  function b64d(s){try{return atob(s)}catch(e){return ''}}
  function unpack(html){
    var m=html.match(/eval\(function\(p,a,c,k,e,d\)\{[\s\S]*?\}\(\s*'([^']*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'([^']*)'\.split\('\|'\)\s*,\s*(\d+)\s*,\s*\{\}\)\)/);
    if(!m)return '';
    var p=m[1],a=parseInt(m[2],10),c=parseInt(m[3],10),k=m[4].split('|');
    function bas(n,b){if(n===0)return '0';var s='',d='0123456789abcdefghijklmnopqrstuvwxyz';while(n>0){s=d[n%b]+s;n=Math.floor(n/b)}return s}
    for(var i=c-1;i>=0;i--){if(k[i]){var t=bas(i,a);p=p.replace(new RegExp('\\b'+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','g'),function(){return k[i]})}}
    return p;
  }
  function decode(html){
    var packed=unpack(html);
    if(!packed)return [];
    var mm=packed.match(/__c0rst96\s*=\s*["']([A-Za-z0-9+/=]+)["']/);
    if(!mm)return [];
    var s1=b64d(mm[1]); if(!s1)return [];
    var cand=[],L=8,i,j;
    for(j=0;j<L;j++)cand[j]=null;
    for(i=0;i<s1.length;i++){
      j=i%L; var b=s1.charCodeAt(i), st={};
      for(var ci=0;ci<CH.length;ci++)st[b^CH.charCodeAt(ci)]=1;
      if(cand[j]===null)cand[j]=st; else{var nc={};for(var kk in cand[j])if(st[kk])nc[kk]=1;cand[j]=nc}
    }
    var keys=[];for(j=0;j<L;j++)keys.push(Object.keys(cand[j]));
    var combos=[[]];
    for(j=0;j<L;j++){var nn=[];for(var x=0;x<combos.length;x++)for(var y=0;y<keys[j].length;y++)nn.push(combos[x].concat([keys[j][y]]));combos=nn;if(combos.length>5000)break}
    for(var z=0;z<combos.length;z++){
      var kb=combos[z],s2='';
      for(i=0;i<s1.length;i++)s2+=String.fromCharCode(s1.charCodeAt(i)^kb[i%L]);
      try{var arr=JSON.parse(b64d(s2));if(arr&&arr.length&&String(arr[0]).indexOf('http')===0)return arr}catch(e){}
    }
    return [];
  }
  var html='';
  try{if(window.result)html=JSON.parse(window.result)}catch(e){}
  if(!html||html.indexOf('__c0rst96')<0){try{html=document.documentElement.outerHTML}catch(e){}}
  var imgs=decode(html);
  if(!imgs.length){
    try{
      var els=document.querySelectorAll('.main_img img, .chapter-img-box img');
      var out=[];
      for(var q=0;q<els.length;q++){var u=els[q].getAttribute('data-src')||els[q].getAttribute('src')||'';if(u&&u.indexOf('http')===0&&u.indexOf('load.gif')<0)out.push(u)}
      imgs=out;
    }catch(e){}
  }
  if(!imgs.length)return '';
  var r='';for(var w=0;w<imgs.length;w++)r+='<img src="'+imgs[w]+'">';
  return r;
})()

